/*
 * Generates the docs of the components, the connection types and the flow file format from the core's declarations
 * (buildCatalog), and llms.txt / llms-full.txt at the repo root for agents. Never edit the generated files by hand.
 * Run from the repo root after changing a component: bun run docs
 * With --check (bun run docs:check, part of bun run lint and CI) it writes nothing and fails when a generated file
 * differs from the one on disk, so the docs never drift from the code.
 */

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { format, resolveConfig } from 'prettier';
// the core's own copy of yaml (the workspaces are isolated: the repo root has no yaml of its own)
import { stringify } from '../../flowtinus.core/node_modules/yaml';
import { buildCatalog, COMPONENT_CATEGORIES, CONNECTION_GROUPS, GITATTRIBUTES, NAME_MAX, REPO_FORMAT, REPO_PATH_MAX, REPO_SCHEMA_BASE_URL, REPO_SCHEMAS, type CatalogComponent, type CatalogSetting } from '../../flowtinus.core/src/index';

const ROOT = join(import.meta.dir, '..', '..');
const COMPONENTS_DIR = import.meta.dir;
const REPO = 'https://github.com/flowtinus-hub/flowtinus/blob/main';
const HEADER = '<!-- Generated by docs/components/generate.ts from @flowtinus/core. Do not edit by hand. -->';

const CHECK = process.argv.includes('--check');

const catalog = buildCatalog();

const code = (v: unknown) => '`' + String(v).replaceAll('`', 'ˋ').replaceAll('|', '\\|').replaceAll('\n', ' ') + '`';
const cell = (text: string) => text.replaceAll('|', '\\|').replaceAll('\n', ' ');

function settingRows(settings: CatalogSetting[], prefix = ''): string[] {
    return settings.flatMap(s => {
        const key = prefix ? `${prefix}.${s.key}` : s.key;
        const details = [
            s.description,
            s.options ? `one of ${s.options.map(o => code(o.value)).join(', ')}` : '',
            s.min !== undefined || s.max !== undefined ? `${s.min ?? '…'} to ${s.max ?? '…'}` : '',
            s.language ? `${s.language}` : '',
            s.connectionType ? `profile type ${(s.connectionTypes ?? [s.connectionType]).map(code).join(', ')}` : '',
            s.spread ? "stored as the item's own `value` and `expression`" : '',
            s.flat ? 'each item is a plain value' : '',
            s.when
                ? `only when ${s.when.map(w => `${w.key} is ${w.values.map(v => code(JSON.stringify(v))).join(' or ')}`).join(' and ')}`
                : '',
            s.placeholder ? `e.g. ${code(s.placeholder)}` : '',
        ].filter(Boolean);
        const row = `| ${code(key)} | ${s.label} | ${s.kind} | ${s.required ? 'yes' : ''} | ${s.default !== undefined ? code(JSON.stringify(s.default)) : ''} | ${cell(details.join('; '))} |`;
        return [row, ...(s.item ? settingRows(s.item, `${key}[]`) : [])];
    });
}

function settingsTable(settings: CatalogSetting[]): string {
    if (settings.length === 0) {
        return 'No settings.\n';
    }
    return (
        ['| Key | Label | Kind | Required | Default | Notes |', '| --- | --- | --- | --- | --- | --- |', ...settingRows(settings)].join(
            '\n',
        ) + '\n'
    );
}

const ports = (list: CatalogComponent['inputs']) =>
    list.length === 0
        ? 'none'
        : list
              .map(p => `${code(p.id)}${p.label ? ` (${p.label})` : ''}${p.optional ? ' optional' : ''}${p.single ? ' one edge only' : ''}`)
              .join(', ');

function componentDoc(c: CatalogComponent): string {
    const category = COMPONENT_CATEGORIES.find(x => x.category === c.category)!.label;
    const facts = [
        `- Type: ${code(c.type)} (${category})`,
        `- Inputs: ${ports(c.inputs)}`,
        `- Outputs: ${ports(c.outputs)}${c.portsFromConfig ? `; ${c.portsFromConfig}` : ''}`,
        `- Error port: ${code('error')} while ${code('onError')} is ${code('divert')}${c.fixedOnError ? ` (On error is ${c.fixedOnError})` : ''}`,
        c.defaultOutputKey
            ? `- Output key: ${code(c.defaultOutputKey)} by default (the node's ${code('outputKey')} changes it)`
            : '- Output key: none (writes into DATA)',
        `- Override: ${c.usesOverride ? "yes (the node's `override: true` makes what it produces the whole DATA)" : 'no'}`,
        `- Writes outside the run: ${c.sideEffects === 'depends on config' ? 'depends on its config (a test run does not write)' : c.sideEffects ? 'yes (a test run does not write)' : 'no'}`,
    ];
    return [
        HEADER,
        `# ${c.label}`,
        c.description,
        facts.join('\n'),
        '## Settings',
        settingsTable(c.settings),
        'Every component also has `onError` (see [the flow format](../flow-format.md#on-error)).',
        ...(c.example ? ['## Example config', '```yaml\n' + stringify(c.example, { lineWidth: 0 }) + '```'] : []),
    ].join('\n\n');
}

function componentsIndex(): string {
    const sections = COMPONENT_CATEGORIES.map(({ category, label }) => {
        const rows = catalog.components
            .filter(c => c.category === category)
            .map(c => `| [${c.label}](${c.type}.md) | ${code(c.type)} | ${cell(c.description.split('. ')[0]!.replace(/\.$/, ''))}. |`);
        return rows.length
            ? [`## ${label}`, '| Component | Type | What it does |\n| --- | --- | --- |\n' + rows.join('\n')].join('\n\n')
            : '';
    }).filter(Boolean);
    return [
        HEADER,
        '# Components',
        'Every component a flow can use, by palette section. Each page has its ports, settings and an example config. Every flow also has a Start and an End ([the flow format](../flow-format.md)).',
        ...sections,
    ].join('\n\n');
}

function connectionsDoc(): string {
    const sections = CONNECTION_GROUPS.map(({ group, label }) => {
        const types = catalog.connectionTypes.filter(t => t.group === group);
        return [
            `## ${label}`,
            ...types.map(t =>
                [
                    `### ${t.label} (${code(t.type)})`,
                    t.description ?? '',
                    '| Field | Label | Kind | Required | Default | Notes |\n| --- | --- | --- | --- | --- | --- |\n' +
                        t.fields
                            .map(
                                f =>
                                    `| ${code(f.key)} | ${f.label} | ${f.kind} | ${f.required ? 'yes' : ''} | ${f.default !== undefined ? code(f.default) : ''} | ${cell(
                                        [
                                            f.secret ? 'names a secret of the workspace (the value is never in the profile)' : '',
                                            f.options ? `one of ${f.options.map(code).join(', ')}` : '',
                                            f.when
                                                ? `only when ${(f.when as { key: string; values: string[] }).key} is ${(f.when as { values: string[] }).values.map(code).join(' or ')}`
                                                : '',
                                        ]
                                            .filter(Boolean)
                                            .join('; '),
                                    )} |`,
                            )
                            .join('\n'),
                    t.inlineFields
                        ? `A component may fill ${t.inlineFields.map(code).join(', ')} in its own config instead of picking a profile.`
                        : '',
                ]
                    .filter(Boolean)
                    .join('\n\n'),
            ),
        ].join('\n\n');
    });
    return [
        HEADER,
        '# Connection types',
        'A connection profile is a reusable way into a system (a database, an API), kept in a workspace for all its projects. A flow refers to it by id; a sensitive field never holds a value, it names one of the secrets of the workspace. Profiles and secrets are created in the editor (the Connections and the Secrets and Variables pages of the workspace).',
        ...sections,
    ].join('\n\n');
}

function flowFormatDoc(): string {
    const f = catalog.flowFile;
    const shape = stringify(f.shape, { lineWidth: 0 });
    return [
        HEADER,
        '# The flow file',
        `A flow is a ${f.format} document, version ${f.version}: what the editor downloads and uploads, what the server keeps as a draft and what an agent reads and writes through the MCP.`,
        '## Shape',
        '```yaml\n' + shape + '```',
        '## Ports',
        f.ports,
        '## The Start',
        catalog.start.description,
        settingsTable(catalog.start.settings),
        '## The End',
        catalog.end.description,
        '## On error',
        catalog.common.description,
        settingsTable(catalog.common.settings),
        '## Connections',
        f.connectionReference,
        '## Calling by expression',
        f.dynamicTarget,
        '## Expressions',
        catalog.expressions.language,
        catalog.expressions.variables.map(v => `- ${v}`).join('\n'),
        '### $FLOW_CURRENT_RUN',
        Object.entries(catalog.expressions.flowCurrentRun)
            .map(([key, what]) => `- \`${key}\`: ${what}`)
            .join('\n'),
        catalog.expressions.valueFields,
        catalog.expressions.keyNames,
        '## Rules',
        'What `validate_flow` (and every run) checks:',
        catalog.rules.map(r => `- ${r}`).join('\n'),
        '## Patterns',
        'Ways to combine the components for common needs. Read them before designing a flow that does one of these.',
        ...catalog.patterns.flatMap(p => [`### ${p.name}`, p.when, p.steps.map(s => `- ${s}`).join('\n')]),
        '## Example',
        '```yaml\n' + f.example + '```',
        repoFormatDoc(),
    ].join('\n\n');
}

function repoFormatDoc(): string {
    const schemaRows = REPO_SCHEMAS.map(
        s =>
            `| [\`${s.file}\`](schemas/${s.file}) | ${s.fileMatch.map(m => `\`${m}\``).join(', ')} | ${(s.schema.title as string).replace('Flowtinus ', '')} |`,
    );
    const vscode = JSON.stringify(
        { 'yaml.schemas': Object.fromEntries(REPO_SCHEMAS.map(s => [`${REPO_SCHEMA_BASE_URL}${s.file}`, s.fileMatch])) },
        null,
        4,
    );
    return [
        '## In a git repository',
        `A workspace mirrored to git is a folder of its own on the environment's branch, in a public format (version ${REPO_FORMAT}) that the app, a person or another tool can write. The name of a project, folder, flow, connection or script is its path; its identity (\`id\`, a UUID in lower case) is in its file, so a rename or a move is a move of the file. Every name is a valid file name everywhere (no \`\\ / : * ? " < > |\`, no name Windows reserves, at most ${NAME_MAX} characters, unique among its siblings whatever the case) and a path in the repository has at most ${REPO_PATH_MAX} characters, so a clone on Windows works.`,
        '```text\n' +
            [
                `.gitattributes                         # ${GITATTRIBUTES.trim()}, written on the first export`,
                '<workspace>/',
                `  workspace.yaml                       # format: ${REPO_FORMAT}`,
                '  connections/<connection name>.yaml   # id, type',
                '  projects/<project name>/',
                '    project.yaml                       # id, description, icon, color',
                '    flows/<folder>/<flow name>.flow.yaml',
                '    scripts/<script path>.ts',
            ].join('\n') +
            '\n```',
        'An empty folder of flows or of scripts keeps a `.gitkeep`. A file anywhere else is not part of the format.',
        '### workspace.yaml',
        `\`format: ${REPO_FORMAT}\`, the version of the format. A change to the format gets a new number.`,
        '### A connection',
        '`connections/<connection name>.yaml` declares a connection: its `id` and its `type` only. Its configuration and credentials stay on each server, so no secret reaches git; a connection that arrives on a server from git is not configured there until someone configures it. Secrets and variables are not in the repository: a flow names them only.',
        '```yaml\nid: 0b6f3c1e-2a7d-4f0e-9c4b-5d8e1a2f3b4c\ntype: sqlserver\n```',
        '### project.yaml',
        "The project's `id`, and its `description`, `icon` and `color`, each optional.",
        '### A flow',
        "`flows/<folder>/<flow name>.flow.yaml` is the flow file described above, with three differences: it has the flow's `id` (required); it has no `name`, which is the file name without `.flow.yaml`; it has no `pinned` outputs, which are test data and stay on the server. It may say `deployed: false` when the flow is not deployed; absent means `true`. A flow names the connections and the flows it calls by id, and scripts by path.",
        'The server writes a flow once it has been deployed: the deployed version, or, after an undeploy, the version deployed last with `deployed: false`. A draft never reaches the repository, and an archived flow, folder or project leaves it.',
        '### A script',
        "`scripts/<script path>.ts`: the project's script, as it is. A script is identified by its path.",
        '### The stable order',
        "Every file the app writes is in one canonical order: a flow's nodes by id, its edges by source, target and then ports, its groups by id, and every key of a node's `config` from a to z (at every depth; lists keep their order). So writing a file the app read gives no diff, and two branches that each add a node rarely conflict. The app reads any order and any YAML formatting (flow style, quotes, CRLF line endings).",
        "Comments are not part of the format: the app drops them when it writes a file. What a comment would say goes in a node's `notes`.",
        '### Versions',
        "A deploy makes a new version only when what the engine runs changed. A version's content hash leaves out `deployed`, the name, the canvas (positions, groups, notes), the pinned outputs, the order of nodes, edges and keys, and line endings (LF or CRLF): changing only `deployed` makes no new version.",
        '### Validation of a tree',
        'The app checks a whole workspace tree before applying it (`validateWorkspaceTree` in the core). An error refuses the tree whole, with the reasons listed: a file that is not valid YAML or does not match its schema (an unknown key included); an `id` missing, not a UUID in lower case, or in two files of a kind; a `workspace.yaml` or a `project.yaml` missing; an edge to a node that does not exist; a call to a flow that is not in the workspace or to a script that is not in the project; a connection a flow uses and the workspace does not declare; a name breaking the rule above or a path too long; two names that differ only in case or Unicode normalization. A warning does not: a declared connection not configured on this server; a secret or variable a flow reads with no value on this server; a comment in a flow file; a repository without `.gitattributes`; a file that is not part of the format (it is left out).',
        '### JSON Schemas',
        'A JSON Schema for each file, for an editor to check the files as they are written:',
        ['| Schema | Files | For |', '| --- | --- | --- |', ...schemaRows].join('\n'),
        'In VS Code, with the YAML extension, in the settings:',
        '```json\n' + vscode + '\n```',
    ].join('\n\n');
}

function llmsTxt(): string {
    return [
        '# Flowtinus',
        '',
        '> Visual data flows: components connected by edges move envelopes (each with a DATA object) from a Start to an End. A remote MCP server (/mcp on the API) lets an agent list components, read and write flow drafts, validate them and test run them.',
        '',
        '## Docs',
        '',
        `- [The flow file](${REPO}/docs/flow-format.md): the YAML an agent writes, ports, expressions, rules, patterns (barrier, incremental load with a checkpoint, lock), a full example`,
        `- [Components](${REPO}/docs/components/README.md): every component, by palette section`,
        `- [Connection types](${REPO}/docs/connections.md): the profiles components connect with`,
        `- [MCP server](${REPO}/docs/mcp/README.md): tools, scopes, personal access tokens, client setup`,
        `- [Runtime](${REPO}/docs/runtime/README.md): supervisors, workers, who runs what`,
        '',
        '## Components',
        '',
        ...catalog.components.map(
            c =>
                `- [${c.label}](${REPO}/docs/components/${c.type}.md) (\`${c.type}\`): ${c.description.split('. ')[0]!.replace(/\.$/, '')}.`,
        ),
        '',
    ].join('\n');
}

const outputs = new Map<string, string>();
for (const c of catalog.components) {
    outputs.set(join(COMPONENTS_DIR, `${c.type}.md`), componentDoc(c));
}
outputs.set(join(COMPONENTS_DIR, 'README.md'), componentsIndex());
outputs.set(join(ROOT, 'docs', 'connections.md'), connectionsDoc());
outputs.set(join(ROOT, 'docs', 'flow-format.md'), flowFormatDoc());
for (const { file, schema } of REPO_SCHEMAS) {
    outputs.set(join(ROOT, 'docs', 'schemas', file), JSON.stringify(schema));
}

// a component that was removed: its page goes too
const removed = readdirSync(COMPONENTS_DIR)
    .filter(file => file.endsWith('.md') && !outputs.has(join(COMPONENTS_DIR, file)))
    .map(file => join(COMPONENTS_DIR, file));

const formatted = new Map<string, string>();
for (const [path, text] of outputs) {
    formatted.set(path, await format(text + '\n', { ...(await resolveConfig(path)), filepath: path }));
}
formatted.set(join(ROOT, 'llms.txt'), llmsTxt());
formatted.set(
    join(ROOT, 'llms-full.txt'),
    [
        llmsTxt(),
        formatted.get(join(ROOT, 'docs', 'flow-format.md')),
        formatted.get(join(ROOT, 'docs', 'connections.md')),
        ...catalog.components.map(c => formatted.get(join(COMPONENTS_DIR, `${c.type}.md`))),
    ]
        .map(text => text!.replace(HEADER + '\n\n', ''))
        .join('\n---\n\n'),
);
if (CHECK) {
    // line endings aside: a Windows checkout may hold the files with CRLF
    const read = (path: string) => (existsSync(path) ? readFileSync(path, 'utf8').replaceAll('\r\n', '\n') : undefined);
    const stale = [...[...formatted].filter(([path, text]) => read(path) !== text).map(([path]) => path), ...removed];
    if (stale.length > 0) {
        console.error(`Generated docs out of date (run bun run docs):\n${stale.map(p => `  ${p}`).join('\n')}`);
        process.exit(1);
    }
    console.log(`The ${formatted.size} generated files match the code.`);
} else {
    mkdirSync(COMPONENTS_DIR, { recursive: true });
    mkdirSync(join(ROOT, 'docs', 'schemas'), { recursive: true });
    for (const path of removed) {
        rmSync(path);
    }
    for (const [path, text] of formatted) {
        writeFileSync(path, text);
    }
    console.log(`Wrote ${formatted.size} files.`);
}
